<script setup lang="ts">
const {user,refresh,logout}=useAuth()
const syncError=useState('account-sync-error',()=> '')
const syncStatus=useState<string>('account-sync-status',()=> 'idle')
const name=ref(''),currentPassword=ref(''),password=ref(''),message=ref('')
onMounted(async()=>{try{await refresh();name.value=user.value?.name||''}catch{message.value='Հաշվի ծառայությունն անհասանելի է'}})
async function save(){try{const result=await $fetch<{user:typeof user.value;reauthenticate:boolean}>('/api/account/profile',{method:'PUT',body:{name:name.value,...(password.value?{password:password.value,currentPassword:currentPassword.value}:{})}});user.value=result.user;password.value='';currentPassword.value='';message.value='Պահպանված է';if(result.reauthenticate){user.value=null;window.dispatchEvent(new Event('factum-auth-changed'));await navigateTo('/login')}}catch(e:any){message.value=e.data?.statusMessage||'Չհաջողվեց պահպանել'}}
</script>
<template><section class="panel mb-6"><template v-if="user"><div class="flex flex-wrap gap-4 items-center"><strong>{{user.name}}</strong><span class="muted">{{user.email}}</span><NuxtLink v-if="user.role!=='USER'" class="gold" to="/admin">Կառավարման վահանակ</NuxtLink><button @click="logout">Դուրս գալ</button></div><p class="account-storage" :class="{synced:syncStatus==='saved'}"><span>{{syncStatus==='saved'?'✓':'◌'}}</span>{{syncStatus==='loading'?'Պահպանված նյութերը բեռնվում են քո հաշվից…':syncStatus==='saving'?'Փոփոխությունները պահպանվում են բազայում…':syncStatus==='saved'?'Պահպանված նյութերդ և առաջընթացը համաժամացված են քո հաշվի հետ։':'Պահպանված նյութերդ պահվում են քո հաշվով և հասանելի են նաև այլ սարքից։'}}</p><details class="mt-4"><summary>Հաշվի կարգավորումներ</summary><form class="grid gap-3 mt-4" @submit.prevent="save"><label>Անուն <input v-model="name" required minlength="2"></label><label>Ընթացիկ գաղտնաբառ <input v-model="currentPassword" type="password" autocomplete="current-password"></label><label>Նոր գաղտնաբառ <input v-model="password" type="password" minlength="12" autocomplete="new-password"></label><button class="gold">Պահպանել</button></form></details></template><template v-else><NuxtLink to="/login" class="gold">Մուտք գործել կամ գրանցվել</NuxtLink><p class="muted mt-2">Մուտք գործեք՝ պահպանված նյութերը տարբեր սարքերում օգտագործելու համար։</p></template><p role="status">{{message}}</p><p v-if="syncError" role="alert">{{syncError}}</p></section></template>
<style scoped>.account-storage{display:flex;gap:8px;align-items:flex-start;margin-top:15px;font-size:11px;line-height:1.9;color:#9bb1cc}.account-storage.synced{color:#95c7ad}.account-storage>span{flex-shrink:0;}input{background:#081326;border:1px solid #35587e;padding:8px;border-radius:6px;max-width:100%}label{display:grid;gap:6px}</style>
